   <!-- Modal Structure -->

   <div id="myModal" class="modal">

      <div class="modal-content">

         <span class="close">&times;</span>

         <img src="<?= $rootUrl ?>assets/images/naac-certi.jpg" alt="">

      </div>

   </div>

   <style>
      .modal {

         position: fixed;

         top: 0;
         left: 0;

         width: 100%;
         height: 100%;

         background: rgba(0, 0, 0, 0.5);

         display: flex;

         justify-content: center;

         align-items: center;

         z-index: 9999;

         display: none;
         /* hidden by default */

      }



      .modal-content {

         background: white;

         padding: 20px;

         width: 30%;

         box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);

         position: relative;

      }

      .close {

         position: absolute;

         right: 0px;

         top: -8px;

         cursor: pointer;

         font-size: 40px;

         color: black !important;

         opacity: 0.8;

      }

      @media (max-width: 767px) {

         .modal-content {

            width: 90%;
            /* Use 90% of screen width */

            max-width: none;
            /* Remove the max width to allow the modal to fill more screen */

            padding: 15px;
            /* Adjust padding for smaller screens */

         }

         .close {

            font-size: 25px;
            /* Smaller close button */

            right: 3px;

            top: -2px;

         }

      }
   </style>

   <script>

      window.onload = function () {

         var modal = document.getElementById("myModal");

         var closeBtn = document.querySelector(".close");

         modal.style.display = "flex"; // Show modal



         closeBtn.onclick = function () {

            modal.style.display = "none";

         };



         window.onclick = function (e) {

            if (e.target === modal) {

               modal.style.display = "none";

            }

         };

      };

   </script>


